cd /tmp; python3 - <<'EOF'
import urllib.request,re
h=urllib.request.urlopen("http://host.docker.internal:8300/").read().decode()
srcs=re.findall(r'(?:src|href)="([^"]+\.js)"',h)
print(srcs[:20])
for s in srcs:
    u=s if s.startswith('http') else "http://host.docker.internal:8300"+s
    try:
        j=urllib.request.urlopen(u).read().decode()
    except Exception as e:
        print(e); continue
    for m in set(re.findall(r'[\w/${}.-]*experiment[\w/${}.-]*',j,re.I)):
        if len(m)>5: print(m)
EOF

cat > /tmp/exp.json <<'EOF'
{
  "name": "wishlist_sync_copy test",
  "feature": 1127,
  "hypothesis": "\"Try it free\" increases add to cart versus \"Start free trial\"",
  "metrics": [
    {"metric": "add_to_cart", "expected_direction": "increase"},
    {"metric": "support_ticket_opened", "expected_direction": "not_increase"}
  ],
  "experiment_rollout": {
    "enabled": false,
    "rollout_percentage": 100,
    "feature_state_value": {"type": "string", "value": "Start free trial"},
    "multivariate_feature_state_values": [
      {"multivariate_feature_option": 94, "percentage_allocation": 50}
    ]
  }
}
EOF
flagsmith api api/v1/environments/[env-021d44ebd9bb7a69]/experiments/ -X POST --input /tmp/exp.json --json -i 2>&1 | head -c 2000

